const MAX_NODES = 16;
const MAX_LINKS = 24;
const MIN_CLEARANCE = 10;
export const sat = (x) => Math.max(0, Math.min(1, x));

export function eligibleGraph(graph) {
  return graph.nodes.length >= 2 && graph.nodes.length <= MAX_NODES && graph.links.length <= MAX_LINKS;
}

export function geometry(graph, pos) {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  let width = 0, height = 0, cy = 0;
  for (const n of graph.nodes) {
    const [x, y] = pos[n.id];
    x0 = Math.min(x0, x);
    y0 = Math.min(y0, y);
    x1 = Math.max(x1, x + n.w);
    y1 = Math.max(y1, y + n.h);
    width += n.w;
    height += n.h;
    cy += y + n.h / 2;
  }
  const count = graph.nodes.length;
  return {width: x1 - x0, height: y1 - y0, w: width / count, h: height / count, cy: cy / count};
}

